import os
for root,dirs,files in os.walk('/workspace'):
 if root.count('/')<4:
  print(root,[(f,round(os.path.getsize(os.path.join(root,f))/1024)) for f in files[:30]])

import subprocess, pathlib
for n in ('main','si'):
 p=subprocess.run(['pdftotext','-layout',f'/workspace/{n}.pdf',f'/workspace/{n}.txt'],capture_output=True,text=True)
 print(n,p.returncode, len(pathlib.Path(f'/workspace/{n}.txt').read_text()),subprocess.check_output(['pdfinfo',f'/workspace/{n}.pdf'],text=True).split('Pages:')[1].splitlines()[0])
for n in ('previous_review_round2.md','17-suggested-reviewers.md','16-journal-editors.md'):
 print('\n',n,'\n',pathlib.Path('/workspace',n).read_text()[:35000])

from pathlib import Path
m=Path('/workspace/main.txt').read_text(); s=Path('/workspace/si.txt').read_text(); old=Path('/workspace/previous_review_round2.md').read_text(); rev=Path('/workspace/17-suggested-reviewers.md').read_text()
for title,txt in [('main',m),('si',s),('old',old),('rev',rev)]:
 print(title,'chars',len(txt),'pages',len(txt.split('\f')))
 if title in ('old','rev'): print(txt)
 else:
  for i,p in enumerate(txt.split('\f')):
   print('PAGE',i+1,'CHARS',len(p),'START',repr(p[:230]))

import re
for line in old.splitlines():
 if re.match(r'(Reviewer \d|Major comments|Minor comments|Recommendation|\d+\.)',line): print(line[:300])
